-- 037_backtest_statistics.sql
-- Numbered 031 until 2026-10-21; renumbered 037 when main-nonQT joined main (main has its own 028 and 029).
-- The migration was applied to new_algo_data as 031 on 2026-10-12: do not re-apply it there. The text below is
-- exactly as applied, so its comments and stored COMMENT texts still call it 031.
--
-- The backtest statistics of LOOP_SPEC v6.2 section 7.4 (T-8b commit (1b); COLUMN_PLAN section
-- 2.6, where this migration is numbered 025) and the backtest twin of the six overlay columns HD
-- ruled on 2026-10-10 (migration 030 holds the live ones).
--
--   backtest.results       thirteen columns, one value a run:
--     the worst day          worst_day, worst_day_date, worst_day_symbol
--     on the sizing capital  max_drawdown_sizing, volatility_sizing, worst_day_sizing,
--                            worst_day_sizing_date, worst_day_sizing_symbol   (futures runs only)
--     the months, the years  monthly_skew, monthly_tail_ratio, calendar_year_returns (jsonb),
--                            losing_years
--     the fill count         total_strategy_fills (total_trades and total_roll_fills exist)
--   backtest.equity_curve  six columns, one value a row, beside risk_detail:
--     the overlay's readings overlay_risk, overlay_risk_jump, overlay_risk_shock,
--                            overlay_gross_leverage, overlay_net_leverage, var_95_1d (futures runs)
-- Every column is NULL-able with no default. The backtest's units are FRACTIONS (the live twins
-- are percent). NO BACKFILL: a run written before this migration keeps NULL in all nineteen.
--
-- COMMENTS RESTATED (a COMMENT replaces the whole text; the rollback restores migration 028's
-- text byte for byte):
--   * backtest.results.total_trades: named the round-trip count beside the two fill counts;
--   * the table comment of backtest.results and the comments of its eleven return statistics:
--     migration 028 wrote them for the convention of its day (every row after the warm-up, 252,
--     the population standard deviation) and said the alignment to the statistics grid belonged
--     to a later migration; the binary this migration ships with takes them on the grid;
--   * trading.live_results.total_dividend_income: 028's text plus one sentence (with nothing to
--     carry, the cell takes the column default 0).
--
-- SAFETY: ADD COLUMN of NULL-able columns with no default is metadata-only; no existing column,
-- value, key, index or view is touched; type-guarded; transactional and idempotent.

BEGIN;
DO $$
DECLARE
    want_results CONSTANT text[][] := ARRAY[['worst_day', 'double precision'], ['worst_day_date', 'date'], ['worst_day_symbol', 'text'], ['max_drawdown_sizing', 'double precision'], ['volatility_sizing', 'double precision'], ['worst_day_sizing', 'double precision'], ['worst_day_sizing_date', 'date'], ['worst_day_sizing_symbol', 'text'], ['monthly_skew', 'double precision'], ['monthly_tail_ratio', 'double precision'], ['calendar_year_returns', 'jsonb'], ['losing_years', 'integer'], ['total_strategy_fills', 'integer']];
    want_curve CONSTANT text[][] := ARRAY[['overlay_risk', 'double precision'], ['overlay_risk_jump', 'double precision'], ['overlay_risk_shock', 'double precision'], ['overlay_gross_leverage', 'double precision'], ['overlay_net_leverage', 'double precision'], ['var_95_1d', 'double precision']];
    o text; p text[]; i int; found text;
BEGIN
    FOREACH o IN ARRAY ARRAY['backtest.results.total_trades', 'backtest.results.total_roll_fills',
            'backtest.results.total_return', 'backtest.results.volatility', 'backtest.results.sharpe_ratio',
            'backtest.results.downside_volatility', 'backtest.results.sortino_ratio',
            'backtest.results.max_drawdown', 'backtest.results.calmar_ratio', 'backtest.results.var_95',
            'backtest.results.cvar_95', 'backtest.results.beta', 'backtest.results.correlation',
            'backtest.equity_curve.risk_detail', 'trading.live_results.total_dividend_income'] LOOP
        p := string_to_array(o, '.');
        IF to_regclass(p[1] || '.' || p[2]) IS NULL THEN RAISE EXCEPTION '031: % does not exist', p[1] || '.' || p[2]; END IF;
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                WHERE table_schema = p[1] AND table_name = p[2] AND column_name = p[3]) THEN
            RAISE EXCEPTION '031: column % does not exist', o;
        END IF;
    END LOOP;
    FOR i IN 1 .. array_length(want_results, 1) LOOP
        SELECT data_type INTO found FROM information_schema.columns
         WHERE table_schema = 'backtest' AND table_name = 'results' AND column_name = want_results[i][1];
        IF found IS NOT NULL AND found <> want_results[i][2] THEN
            RAISE EXCEPTION 'backtest.results.% exists with another type (%)', want_results[i][1], found;
        END IF;
    END LOOP;
    FOR i IN 1 .. array_length(want_curve, 1) LOOP
        SELECT data_type INTO found FROM information_schema.columns
         WHERE table_schema = 'backtest' AND table_name = 'equity_curve' AND column_name = want_curve[i][1];
        IF found IS NOT NULL AND found <> want_curve[i][2] THEN
            RAISE EXCEPTION 'backtest.equity_curve.% exists with another type (%)', want_curve[i][1], found;
        END IF;
    END LOOP;
END $$;
ALTER TABLE backtest.results
    ADD COLUMN IF NOT EXISTS worst_day double precision,
    ADD COLUMN IF NOT EXISTS worst_day_date date,
    ADD COLUMN IF NOT EXISTS worst_day_symbol text,
    ADD COLUMN IF NOT EXISTS max_drawdown_sizing double precision,
    ADD COLUMN IF NOT EXISTS volatility_sizing double precision,
    ADD COLUMN IF NOT EXISTS worst_day_sizing double precision,
    ADD COLUMN IF NOT EXISTS worst_day_sizing_date date,
    ADD COLUMN IF NOT EXISTS worst_day_sizing_symbol text,
    ADD COLUMN IF NOT EXISTS monthly_skew double precision,
    ADD COLUMN IF NOT EXISTS monthly_tail_ratio double precision,
    ADD COLUMN IF NOT EXISTS calendar_year_returns jsonb,
    ADD COLUMN IF NOT EXISTS losing_years integer,
    ADD COLUMN IF NOT EXISTS total_strategy_fills integer;
ALTER TABLE backtest.equity_curve
    ADD COLUMN IF NOT EXISTS overlay_risk double precision,
    ADD COLUMN IF NOT EXISTS overlay_risk_jump double precision,
    ADD COLUMN IF NOT EXISTS overlay_risk_shock double precision,
    ADD COLUMN IF NOT EXISTS overlay_gross_leverage double precision,
    ADD COLUMN IF NOT EXISTS overlay_net_leverage double precision,
    ADD COLUMN IF NOT EXISTS var_95_1d double precision;
COMMENT ON COLUMN backtest.results.worst_day IS $c031$Fraction: the smallest grid return of the account, r^a = grid level / previous grid level - 1 (the P&L of every row folded into the return is in it). NULL while the series has no return. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.worst_day (migration 030), which is in PERCENT.$c031$;
COMMENT ON COLUMN backtest.results.worst_day_date IS $c031$The date of worst_day: the first grid date that has the smallest grid return. NULL while the series has no return. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.worst_day_date (migration 030).$c031$;
COMMENT ON COLUMN backtest.results.worst_day_symbol IS $c031$The symbol whose P&L over the rows folded into the worst day's grid return (worst_day, worst_day_date) is the most negative; equal losses name the first symbol in text order; NULL when no symbol lost over those rows (the day's loss is costs alone) or the series has no return. The rows folded into a grid return are every stored date after the previous grid date (for the first return: after the base row's date) through the return's own date (a Saturday point or a thin date lands in the next grid return), taken together. A symbol's P&L over them is the sum of backtest.final_positions.realized_pnl on those dates plus the change across them of backtest.final_positions.unrealized_pnl (the open position's unrealised level; 0 on every futures row, which books its whole daily move as realised), summed over the run's sleeves (a symbol two sleeves hold is the book's). It is the P&L of LOOP_SPEC section 6.6, before costs. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.worst_day_symbol (migration 030).$c031$;
COMMENT ON COLUMN backtest.results.max_drawdown_sizing IS $c031$Fraction of the sizing capital, positive (0.01 is one percentage point): the largest fall of the running SUM of r^s from its running peak (the sum and its peak start at 0). FUTURES runs only; NULL on an equity run's row, which stores no sizing capital. r^s of a grid return = its dollar P&L (the difference of two grid levels, so the P&L of every folded row is in it) / E_t, never compounded. E_t is risk_detail.sizing_capital of the last backtest.equity_curve row on or before the grid date that carries one: the grid row's own where it has one; a row with no capital of its own (an all-JUNK cycle, a refused overlay) reads the last one before it; a folded Saturday point adds to the P&L and does not supply the capital of a grid row that has its own. The series starts at the first grid return whose date has such a capital. NULL with fewer than 2 such returns. The account twin is max_drawdown (compounded, on the account value). Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.max_drawdown_sizing (migration 030), which is in PERCENT.$c031$;
COMMENT ON COLUMN backtest.results.volatility_sizing IS $c031$Fraction, annualised, REALISED, on the sizing capital: the sample standard deviation (n - 1) of r^s x sqrt(K). FUTURES runs only; NULL on an equity run's row, which stores no sizing capital. r^s of a grid return = its dollar P&L (the difference of two grid levels, so the P&L of every folded row is in it) / E_t, never compounded. E_t is risk_detail.sizing_capital of the last backtest.equity_curve row on or before the grid date that carries one: the grid row's own where it has one; a row with no capital of its own (an all-JUNK cycle, a refused overlay) reads the last one before it; a folded Saturday point adds to the P&L and does not supply the capital of a grid row that has its own. The series starts at the first grid return whose date has such a capital. NULL with fewer than 2 such returns. The account twin is volatility; the forward figure is backtest.equity_curve.overlay_risk. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.volatility_sizing (migration 030), which is in PERCENT.$c031$;
COMMENT ON COLUMN backtest.results.worst_day_sizing IS $c031$Fraction of the sizing capital: the smallest r^s. FUTURES runs only; NULL on an equity run's row, which stores no sizing capital. r^s of a grid return = its dollar P&L (the difference of two grid levels, so the P&L of every folded row is in it) / E_t, never compounded. E_t is risk_detail.sizing_capital of the last backtest.equity_curve row on or before the grid date that carries one: the grid row's own where it has one; a row with no capital of its own (an all-JUNK cycle, a refused overlay) reads the last one before it; a folded Saturday point adds to the P&L and does not supply the capital of a grid row that has its own. The series starts at the first grid return whose date has such a capital. NULL with fewer than 2 such returns. The account twin is worst_day. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.worst_day_sizing (migration 030), which is in PERCENT.$c031$;
COMMENT ON COLUMN backtest.results.worst_day_sizing_date IS $c031$The date of worst_day_sizing: the first grid date that has the smallest r^s. NULL where worst_day_sizing is. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.worst_day_sizing_date (migration 030).$c031$;
COMMENT ON COLUMN backtest.results.worst_day_sizing_symbol IS $c031$The symbol whose P&L over the rows folded into the grid return of worst_day_sizing_date is the most negative; NULL where worst_day_sizing is, or when no symbol lost over those rows. The rows folded into a grid return are every stored date after the previous grid date (for the first return: after the base row's date) through the return's own date (a Saturday point or a thin date lands in the next grid return), taken together. A symbol's P&L over them is the sum of backtest.final_positions.realized_pnl on those dates plus the change across them of backtest.final_positions.unrealized_pnl (the open position's unrealised level; 0 on every futures row, which books its whole daily move as realised), summed over the run's sleeves (a symbol two sleeves hold is the book's). It is the P&L of LOOP_SPEC section 6.6, before costs. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.worst_day_sizing_symbol (migration 030).$c031$;
COMMENT ON COLUMN backtest.results.monthly_skew IS $c031$A ratio. The sample skewness of the account's returns of its COMPLETE calendar months: the adjusted Fisher-Pearson coefficient G1 = n / ((n - 1)(n - 2)) x sum(((x - mean) / s)^3), s the sample standard deviation (n - 1). A month's return is compounded from its grid returns. A month is complete when its first calendar day is after the base row's date and its last calendar day is on or before the date of the run's last equity-curve row (the month the statistics start in and the month the run ends in are partial unless the run ends on the month's last day). NULL under 12 complete months. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.monthly_skew (migration 030).$c031$;
COMMENT ON COLUMN backtest.results.monthly_tail_ratio IS $c031$A ratio. Over the same complete calendar months as monthly_skew: the mean of the monthly returns at or above their 95th percentile divided by the absolute value of the mean of the monthly returns at or below their 5th percentile, the percentiles by linear interpolation between order statistics. NULL under 12 complete months, or when the lower mean is 0. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.monthly_tail_ratio (migration 030).$c031$;
COMMENT ON COLUMN backtest.results.calendar_year_returns IS $c031${"YYYY": {"return": fraction, "partial": true or false}} on the account: each calendar year's return compounded from its grid returns. A year is full (partial false) when its 1 January is after the base row's date and its 31 December is on or before the date of the run's last equity-curve row; a partial first or last year is shown and flagged. An empty object while the series has no return. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.calendar_year_returns (migration 030), which is in PERCENT.$c031$;
COMMENT ON COLUMN backtest.results.losing_years IS $c031$The count of FULL calendar years of calendar_year_returns with a negative return; a partial first or last year is shown there and never counted here. Taken on the run's statistics grid, described in the comment on the table (a futures run: the Sunday-to-Friday UTC dates on which at least 9 stored symbols of the run's own bars printed a bar, K = 311.0574 sessions a year; an equity run: its own rows, the NYSE sessions, K = 252), over the equity-curve rows after the warm-up: the first row after the warm-up is the base and never a return. Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031. The twin of trading.live_results.losing_years (migration 030).$c031$;
COMMENT ON COLUMN backtest.results.total_strategy_fills IS $c031$The run's count of the ACCOUNT's STRATEGY fills AFTER NETTING BETWEEN SLEEVES, not the sleeve rows of backtest.executions (those are unchanged: one row per sleeve with its netting_adjustment). Per contract and bar the sleeves' STRATEGY rows are summed: a full cross is 0 fills (no execution happened), a partial offset is 1, two sleeves on the same side are 1, a single sleeve is 1, and a reversal through zero is one fill: a reversal stored as two same-side rows of one contract and bar (the close, then the open) is one order the account sent, and the count is of account orders (HD 2026-10-10). On a run of one sleeve it equals the count of STRATEGY rows less one for each such reversal. Its own total beside total_trades (the round trips) and total_roll_fills (the ROLL legs): executions = STRATEGY rows + ROLL legs (+ BORROW rows on the equity book). Counted over every execution of the run by the helper the trade statistics use (BacktestMetricsCalculator::account_fills), the one definition with trading.live_results.total_strategy_fills (migration 030). Rows written before migration 031 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 031.$c031$;
COMMENT ON COLUMN backtest.equity_curve.overlay_risk IS $c031$A fraction of the sizing capital, annualised, FORWARD: R = sqrt(x' Sigma x), the expected annual volatility of the stored book, Sigma the overlay's annualised covariance of the gate window (the last 252 dates, on the window's own bars a year). THE FIGURE TO COMPARE WITH THE RISK TARGET tau (CONSERVATIVE 0.20). LIMIT: R_max = 2.25 x tau (risk.json carver module and LOOP_SPEC v6.2 section 12 D1): 0.45 on CONSERVATIVE. COVERAGE: the figure covers the contracts inside the overlay's covariance that day, so it understates the book on a day when a held contract is left out of it. Two cases are left out, and they are not the same. (1) A participant of the pass that is outside the covariance: a contract with too short a history, or a held row fixed at its last usable close (a held symbol with no series, close or multiplier today). It is outside R and inside both leverage readings, and inside the shock reading when the window gives it a sigma. (2) A symbol with no usable price at all (no close or multiplier to value it on): it is not in the pass and is in no reading. NULL also on a blind window (fewer than 21 complete dates; risk_detail.overlay_blind), where no covariance reading exists. FUTURES runs only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a row, the book's, whatever its sleeves); NULL on every row of an equity run, on the seed row (the run's first row, at the start date), on the warm-up rows and on a row with no risk_detail (an all-JUNK cycle, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THE RUN STORES FOR THIS ROW'S DATE (backtest.final_positions of the date, summed over the sleeves), on the weights x_i = quantity x multiplier x raw close at the signal date (the bar date before the row's) / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. NOT backtest.results.volatility or volatility_sizing (realised). LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 031 hold NULL. The twin of trading.live_results.overlay_risk (migration 030). Migration 031.$c031$;
COMMENT ON COLUMN backtest.equity_curve.overlay_risk_jump IS $c031$A fraction of the sizing capital, annualised, FORWARD: R_jump = sqrt(x' Sigma_jump x), the window's correlations on each contract's own jump sigma in place of its window sigma. LIMIT: R_jump_max = 4.5 x tau (risk.json carver module and LOOP_SPEC v6.2 section 12 D1): 0.90 on CONSERVATIVE. COVERAGE: the figure covers the contracts inside the overlay's covariance that day, so it understates the book on a day when a held contract is left out of it. Two cases are left out, and they are not the same. (1) A participant of the pass that is outside the covariance: a contract with too short a history, or a held row fixed at its last usable close (a held symbol with no series, close or multiplier today). It is outside R and inside both leverage readings, and inside the shock reading when the window gives it a sigma. (2) A symbol with no usable price at all (no close or multiplier to value it on): it is not in the pass and is in no reading. NULL also on a blind window. FUTURES runs only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a row, the book's, whatever its sleeves); NULL on every row of an equity run, on the seed row (the run's first row, at the start date), on the warm-up rows and on a row with no risk_detail (an all-JUNK cycle, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THE RUN STORES FOR THIS ROW'S DATE (backtest.final_positions of the date, summed over the sleeves), on the weights x_i = quantity x multiplier x raw close at the signal date (the bar date before the row's) / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 031 hold NULL. The twin of trading.live_results.overlay_risk_jump (migration 030). Migration 031.$c031$;
COMMENT ON COLUMN backtest.equity_curve.overlay_risk_shock IS $c031$A fraction of the sizing capital, annualised, FORWARD: R_shock = sum of |x_i| x sigma_i, each contract on its own window sigma, as if every correlation were 1. LIMIT: R_shock_max = 4.0 x tau (risk.json carver module and LOOP_SPEC v6.2 section 12 D1): 0.80 on CONSERVATIVE. It includes a participant of the pass that is outside the covariance when the window gives it a sigma of its own (a contract whose history is too short for the covariance; a held row fixed at its last usable close is a participant too, inside both leverage readings and inside this reading only with such a sigma), so it covers more of the book than overlay_risk. A symbol with no usable price at all (no close or multiplier to value it on) is not in the pass and is in no reading. NULL also on a blind window. FUTURES runs only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a row, the book's, whatever its sleeves); NULL on every row of an equity run, on the seed row (the run's first row, at the start date), on the warm-up rows and on a row with no risk_detail (an all-JUNK cycle, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THE RUN STORES FOR THIS ROW'S DATE (backtest.final_positions of the date, summed over the sleeves), on the weights x_i = quantity x multiplier x raw close at the signal date (the bar date before the row's) / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 031 hold NULL. The twin of trading.live_results.overlay_risk_shock (migration 030). Migration 031.$c031$;
COMMENT ON COLUMN backtest.equity_curve.overlay_gross_leverage IS $c031$A multiple of the sizing capital, of the row's stored book: L = sum of |x_i| over every participant of the pass, a held row fixed at its last usable close included; a symbol with no usable price at all (no close or multiplier to value it on) is not in the pass and is in no reading. LIMIT: max_gross_leverage 8.0 (risk.json carver module and LOOP_SPEC v6.2 section 12 D1). Stored on a blind window too. FUTURES runs only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a row, the book's, whatever its sleeves); NULL on every row of an equity run, on the seed row (the run's first row, at the start date), on the warm-up rows and on a row with no risk_detail (an all-JUNK cycle, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THE RUN STORES FOR THIS ROW'S DATE (backtest.final_positions of the date, summed over the sleeves), on the weights x_i = quantity x multiplier x raw close at the signal date (the bar date before the row's) / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 031 hold NULL. The twin of trading.live_results.overlay_gross_leverage (migration 030). Migration 031.$c031$;
COMMENT ON COLUMN backtest.equity_curve.overlay_net_leverage IS $c031$A multiple of the sizing capital, SIGNED, of the row's stored book: L_net = sum of x_i over the same participants as overlay_gross_leverage (a net short book is negative). LIMIT: max_net_leverage 6.0 (risk.json carver module and LOOP_SPEC v6.2 section 12 D1), applied to its ABSOLUTE value. Stored on a blind window too. FUTURES runs only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a row, the book's, whatever its sleeves); NULL on every row of an equity run, on the seed row (the run's first row, at the start date), on the warm-up rows and on a row with no risk_detail (an all-JUNK cycle, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THE RUN STORES FOR THIS ROW'S DATE (backtest.final_positions of the date, summed over the sleeves), on the weights x_i = quantity x multiplier x raw close at the signal date (the bar date before the row's) / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 031 hold NULL. The twin of trading.live_results.overlay_net_leverage (migration 030). Migration 031.$c031$;
COMMENT ON COLUMN backtest.equity_curve.var_95_1d IS $c031$Dollars, positive, FORWARD: the one-day 95 percent value-at-risk of the stored book, 1.645 x overlay_risk / sqrt(the gate window's bars a year) x E_t (risk_detail.sizing_capital): the same covariance as overlay_risk, a normal one-sided 95 percent point, one trading day. No limit is read against it. COVERAGE: the figure covers the contracts inside the overlay's covariance that day, so it understates the book on a day when a held contract is left out of it. Two cases are left out, and they are not the same. (1) A participant of the pass that is outside the covariance: a contract with too short a history, or a held row fixed at its last usable close (a held symbol with no series, close or multiplier today). It is outside R and inside both leverage readings, and inside the shock reading when the window gives it a sigma. (2) A symbol with no usable price at all (no close or multiplier to value it on): it is not in the pass and is in no reading. NULL where overlay_risk is. FUTURES runs only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a row, the book's, whatever its sleeves); NULL on every row of an equity run, on the seed row (the run's first row, at the start date), on the warm-up rows and on a row with no risk_detail (an all-JUNK cycle, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THE RUN STORES FOR THIS ROW'S DATE (backtest.final_positions of the date, summed over the sleeves), on the weights x_i = quantity x multiplier x raw close at the signal date (the bar date before the row's) / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. NOT backtest.results.var_95 (historical, a fraction of the account, of the whole run). LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 031 hold NULL. The twin of trading.live_results.var_95_1d (migration 030). Migration 031.$c031$;
COMMENT ON TABLE backtest.results IS $c031$One row per run: the run's performance statistics. THE RETURN STATISTICS (total_return, volatility, sharpe_ratio, sortino_ratio, downside_volatility, max_drawdown, calmar_ratio, var_95, cvar_95, beta, correlation, and migration 031's worst_day, the three statistics on the sizing capital and the yearly returns) are FRACTIONS (trading.live_results stores percent). THE STATISTICS GRID: the run's equity-curve rows after the warm-up (one row per UTC date, the last; the warm-up sits inside the configured window and its rows are dropped; the first row after it is the base, the level the first return is taken on, and never a return) are folded onto the grid and the returns are taken on the grid's LEVELS, so the P&L of a row dated off the grid (a Saturday point, a thin date) lands in the next grid return and nothing is dropped. A futures run's grid is the Sunday-to-Friday UTC dates on which at least 9 distinct stored symbols of the run's own bars printed a bar; an equity run's grid is its own rows (the NYSE sessions). Every annualised figure uses K, the sessions a year of that grid, handed to the run by the configuration (311.0574 futures, 252 equities) and recorded as statistics_K in backtest.run_metadata.portfolio_config: the grid and the K of trading.live_results. total_return alone is taken on every row after the warm-up. Rows written before migration 031 keep the earlier definitions: every row after the warm-up, 252, the population standard deviation. THE TRADE STATISTICS (total_trades, win_rate, profit_factor, avg_win, avg_loss, max_win, max_loss, avg_holding_period) are the book's account fills after netting between sleeves, in dollars. A trade is an ACCOUNT fill that reduces, closes or flips a non-zero net position in a contract. Account fills are the book's: the STRATEGY rows of one contract on one bar netted across the sleeves (a full cross is no fill, a partial offset is one fill of the net size); ROLL and BORROW rows are never a trade. A trade's P&L is in DOLLARS: closed quantity x (fill price - average entry price) x the side held x the point value, less the closing fill's cost after netting; the opening fills' costs are not inside a trade, with one exception: a fill through zero (a reversal) is ONE account fill with one cost, and its whole cost, the part that opens the new position included, is charged to the trade it closes. Rows written before migration 028 keep the earlier definitions. THE THREE COUNTS, each its own total: total_trades (round trips), total_strategy_fills (the account's STRATEGY fills), total_roll_fills (the ROLL legs).$c031$;
COMMENT ON COLUMN backtest.results."total_return" IS $c031$Fraction. (last level - first level) / first level of the equity curve after the warm-up, every row counted (a level, not folded onto the statistics grid); not annualised.$c031$;
COMMENT ON COLUMN backtest.results."volatility" IS $c031$Fraction, annualised, REALISED: the sample standard deviation (n - 1) of the grid returns x sqrt(K). 0 with fewer than two returns. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."sharpe_ratio" IS $c031$The mean grid return x K over volatility, risk-free rate 0; 0 when volatility is 0. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."downside_volatility" IS $c031$Fraction, annualised: sqrt(the sum of min(r, 0)^2 over EVERY grid return / n) x sqrt(K), target 0; a return at or above 0 counts as a zero. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."sortino_ratio" IS $c031$The mean grid return x K over downside_volatility; 999 when there is no downside and the mean is not negative. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."max_drawdown" IS $c031$Fraction, positive: the largest fall from a running peak of the grid levels after the warm-up, the peak starting at the base (the first level after the warm-up). Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."calmar_ratio" IS $c031$The annualised return on the grid, the CAGR (1 + R)^(K / n) - 1 with R the return from the base to the last grid level and n the count of grid returns, over max_drawdown; 999 when there is no drawdown and the CAGR is not negative. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."var_95" IS $c031$Fraction of one grid return, positive for a loss: minus the return at position floor(0.05 x n) of the grid returns sorted ascending. Historical, not parametric. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."cvar_95" IS $c031$Fraction of one grid return, positive for a loss: minus the mean of the floor(0.05 x n) + 1 lowest grid returns, the var_95 observation included, so it is never smaller than var_95. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."beta" IS $c031$NOT a market beta: the slope of the regression of a grid return on the grid return before it, of the book's own returns (lag-1 autocorrelation). No benchmark enters it. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."correlation" IS $c031$NOT a correlation with a market: the lag-1 autocorrelation of the book's own grid returns. No benchmark enters it. Taken on the run's statistics grid with its sessions a year K (see the comment on the table). Rows written before migration 031 keep the earlier definition.$c031$;
COMMENT ON COLUMN backtest.results."total_trades" IS $c031$ROUND TRIPS (LOOP_SPEC v6.2 sections 7.4 and 10): the count of trades, not the count of backtest.executions rows and not the count of fills: the account's STRATEGY fills are total_strategy_fills and the ROLL legs total_roll_fills, each its own total. The engine's rule, unchanged by migration 031. A trade is an ACCOUNT fill that reduces, closes or flips a non-zero net position in a contract. Account fills are the book's: the STRATEGY rows of one contract on one bar netted across the sleeves (a full cross is no fill, a partial offset is one fill of the net size); ROLL and BORROW rows are never a trade. A trade's P&L is in DOLLARS: closed quantity x (fill price - average entry price) x the side held x the point value, less the closing fill's cost after netting; the opening fills' costs are not inside a trade, with one exception: a fill through zero (a reversal) is ONE account fill with one cost, and its whole cost, the part that opens the new position included, is charged to the trade it closes. A position under 1e-9 contracts or shares after a fill is flat. Rows written before migration 028 keep the earlier definition.$c031$;
COMMENT ON COLUMN trading.live_results."total_dividend_income" IS $c031$Dollars, cumulative: the dividend cash of the book through this date. Each dividend event on record (trading.corp_action_applied) counts its dividend per share x the shares of the trading.positions row dated the ex-date, and is dated on the ex-date row: that row carries it once the next run has settled it, and every later row carries it. It need not equal the sum of corp_action_applied.total_cash, and the two differ for a reason: total_cash is computed on qty_held, the holding of the row dated the day BEFORE the ex-date, which does not yet hold the shares the run of the ex-date buys; that run fills at the close before the ex-date, the cum-dividend close, so the shares it buys carry the dividend and this column counts them. An event with no position row on its ex-date is counted on qty_held. A run that cannot read the dividend record or an ex-date position row logs an ERROR and writes no new figure: its own row carries the figure of the Day T-1 row and the Day T-1 row is left as it is. With nothing to carry (no Day T-1 row, a NULL cell on it, or the read of it failing too) the run's own cell takes the column default, 0. THIS COLUMN IS THE DIVIDEND INCOME (T-8D-2 R44 (b)): the cash a holder of the ex-date row's shares is paid. Informational ONLY and never added to total_pnl. NO DIVIDEND CASH IS CREDITED ANYWHERE in the equity book: no cash row is written and no P&L, value or equity-curve column has a dividend term. What a dividend does to the book is one thing: the run after the ex-date divides the average_price of the ex-date row by 1 + dividend / the raw close of the ex-date, and the bars are total-return adjusted, so the ex-date row's unrealised P&L rises by shares x average_price x dividend / (close + dividend). That amount is basis-weighted, not cash: it is a third figure, equal neither to this column's nor to total_cash (META, ex-date 2026-06-15: 3.606652 in the P&L; 3.752281 here, 7.147202 shares x 0.525; 3.742124 in total_cash, 7.127855 shares x 0.525). Written by the equity runner; the futures runners do not write it. Rows written before migration 028 keep the earlier figure: the sum of total_cash, first carried by the row after the ex-date.$c031$;
COMMIT;
